260: static std::vector<freesasa_structure *>
261: get_structures(std::FILE *input,
262:                const struct cli_state *state)
263: {
264:     int n = 0, n2 = 0;
265:     std::vector<freesasa_structure *> structures;
266:     freesasa_structure *tmp;
267: 
268:     if ((state->structure_options & FREESASA_SEPARATE_CHAINS) ||
269:         (state->structure_options & FREESASA_SEPARATE_MODELS)) {
270:         if (state->cif) {
271:             structures = freesasa_cif_structure_array(input, &n, state->classifier, state->structure_options);
272:         } else {
273:             // TODO this hack needed since PDB implementation is in C
274:             freesasa_structure **db_ptr_structs = freesasa_structure_array(input, &n, state->classifier, state->structure_options);
275:             structures.reserve(n);
276:             for (int i = 0; i < n; ++i) {
277:                 structures.push_back(std::move(db_ptr_structs[i]));
278:             }
279:         }
280:     } else {
281:         n = 1;
282:         if (state->cif) {
283:             structures.emplace_back(freesasa_structure_from_cif(input, state->classifier, state->structure_options));
284:         } else {
285:             structures.emplace_back(freesasa_structure_from_pdb(input, state->classifier, state->structure_options));
286:         }
287:         if (structures[0] == NULL) {
288:             abort_msg("invalid input");
289:         }
290:     }
291: 
292:     /* get chain-groups (if requested) */
293:     if (state->chain_groups.size() > 0) {
294:         n2 = n;
295:         for (int i = 0; i < state->chain_groups.size(); ++i) {
296:             for (int j = 0; j < n; ++j) {
297:                 // TODO make this function pdb and cif compatible.
298:                 tmp = freesasa_structure_get_chains_lcl(structures[j], &state->chain_groups[i],
299:                                                         state->classifier, state->structure_options);
300:                 if (tmp != NULL) {
301:                     ++n2;
302:                     structures.reserve(n2);
303:                     structures.push_back(tmp);
304:                 } else {
305:                     abort_msg("at least one of the requested chains not found in structure");
306:                 }
307:             }
308:         }
309:         n = n2;
310:     }
311: 
312:     if (n == 0) {
313:         abort_msg("invalid input");
314:     }
315: 
316:     return structures;
317: }
