319: static freesasa_node *
320: run_analysis(std::vector<freesasa_structure *> structures,
321:              const char *name,
322:              const struct cli_state *state)
323: {
324:     int name_len = strlen(name);
325:     freesasa_node *tree = freesasa_tree_new(), *tmp_tree, *structure_node;
326:     const freesasa_result *result;
327:     freesasa_selection *sel;
328:     char *name_i = (char *)malloc(name_len + 10);
329: 
330:     if (tree == NULL) abort_msg("failed to initialize result-tree");
331:     if (name_i == NULL) abort_msg("memory failure");
332: 
333:     /* perform calculation on each structure */
334:     for (auto structure : structures) {
335:         strcpy(name_i, name);
336:         if (structures.size() > 1 && (state->structure_options & FREESASA_SEPARATE_MODELS))
337:             snprintf(name_i + strlen(name_i), 9, ":%d", freesasa_structure_model(structure));
338: 
339:         tmp_tree = freesasa_calc_tree(structure, &state->parameters, name_i);
340:         if (tmp_tree == NULL) abort_msg("can't calculate SASA");
341: 
342:         structure_node =
343:             freesasa_node_children(freesasa_node_children(tmp_tree));
344:         result = freesasa_node_structure_result(structure_node);
345: 
346:         /* Calculate selections for each structure */
347:         if (state->n_select > 0) {
348:             for (int c = 0; c < state->n_select; ++c) {
349:                 sel = freesasa_selection_new(state->select_cmd[c], structure, result);
350:                 if (sel != NULL) {
351:                     freesasa_node_structure_add_selection(structure_node, sel);
352:                 } else {
353:                     abort_msg("illegal selection");
354:                 }
355:                 freesasa_selection_free(sel);
356:             }
357:         }
358: 
359:         if (freesasa_tree_join(tree, &tmp_tree) != FREESASA_SUCCESS) {
360:             abort_msg("failed joining result-trees");
361:         }
362:     }
363: 
364:     return tree;
365: }
