388: static void
389: state_add_chain_groups(const char *cmd, struct cli_state *state)
390: {
391:     int err = 0;
392:     char *str;
393:     const char *token;
394:     char a;
395: 
396:     /* check that string is valid */
397:     for (size_t i = 0; i < strlen(cmd); ++i) {
398:         a = cmd[i];
399:         if (a != '+' &&
400:             !(a >= 'a' && a <= 'z') && !(a >= 'A' && a <= 'Z') &&
401:             !(a >= '0' && a <= '9')) {
402:             error("character '%c' not valid chain ID in --chain-groups, "
403:                   "valid characters are [A-z0-9] and '+' as separator",
404:                   a);
405:             ++err;
406:         }
407:     }
408: 
409:     /* extract chain groups */
410:     if (err == 0) {
411:         auto groups = split(cmd, "\\+");
412:         for (auto &group : groups) {
413:             size_t n = group.size();
414:             const char **chains = (const char **)malloc(n * sizeof(char *));
415:             for (size_t i = 0; i < n; ++i) {
416:                 const char chain[2] = {group[i], '\0'};
417:                 chains[i] = strdup(chain);
418:             }
419:             state->chain_groups.push_back({.chains = chains, .n = n});
420:         }
421:     } else {
422:         abort_msg("aborting");
423:     }
424: }
