426: static void
427: state_add_long_chain_groups(const char *cmd, struct cli_state *state)
428: {
429:     auto groups = split(cmd, "\\+");
430:     for (auto &group : groups) {
431:         auto chains = split(group, "\\/");
432:         size_t n = chains.size();
