171: json_object *
172: freesasa_node2json(freesasa_node *node,
173:                    int exclude_type,
174:                    int options)
175: {
176:     json_object *obj, *array = NULL;
177:     int lowest = 0;
178:     int type = freesasa_node_type(node);
179:     freesasa_node *child = freesasa_node_children(node);
180:     if (child) {
181:         if (freesasa_node_type(child) == exclude_type) lowest = 1;
182:         if (!lowest) {
183:             array = json_object_new_array();
184:         }
185:     }
186: 
187:     switch (type) {
188:     case FREESASA_NODE_RESULT:
189:         obj = array;
190:         break;
191:     case FREESASA_NODE_STRUCTURE:
192:         obj = freesasa_json_structure(node, options);
193:         if (!lowest) json_object_object_add(obj, "chains", array);
194:         break;
195:     case FREESASA_NODE_CHAIN:
196:         obj = freesasa_json_chain(node, options);
197:         if (!lowest) json_object_object_add(obj, "residues", array);
198:         break;
199:     case FREESASA_NODE_RESIDUE:
200:         obj = freesasa_json_residue(node, options);
201:         if (!lowest) json_object_object_add(obj, "atoms", array);
202:         break;
203:     case FREESASA_NODE_ATOM:
204:         obj = freesasa_json_atom(node, options);
205:         break;
206:     case FREESASA_NODE_ROOT:
207:     default:
208:         assert(0 && "Tree illegal");
209:     }
210: 
211:     if (!lowest) {
212:         while (child) {
213:             json_object_array_add(array, freesasa_node2json(child, exclude_type, options));
214:             child = freesasa_node_next(child);
215:         }
216:     }
217:     return obj;
218: }
