263: int freesasa_write_json(FILE *output,
264:                         freesasa_node *root,
265:                         int options)
266: 
267: {
268:     assert(freesasa_node_type(root) == FREESASA_NODE_ROOT);
269: 
270:     json_object *results = json_object_new_array(),
271:                 *json_root = json_object_new_object();
272:     freesasa_node *child = freesasa_node_children(root);
273: 
274:     json_object_object_add(json_root, "source", json_object_new_string(freesasa_string));
275:     json_object_object_add(json_root, "length-unit", json_object_new_string("Ångström"));
276:     json_object_object_add(json_root, "results", results);
277:     while (child) {
278:         json_object_array_add(results, json_result(child, options));
279:         child = freesasa_node_next(child);
280:     }
281: 
282:     fputs(json_object_to_json_string_ext(json_root, JSON_C_TO_STRING_PRETTY), output);
283:     json_object_put(json_root);
284: 
285:     fflush(output);
286:     if (ferror(output)) {
287:         return fail_msg(strerror(errno));
288:     }
289:     return FREESASA_SUCCESS;
