349: static int
350: node2xml(xmlNodePtr *xml_node,
351:          freesasa_node *node,
352:          int exclude_type,
353:          int options)
354: {
355:     freesasa_node *child;
356:     xmlNodePtr xml_child = NULL;
357: 
358:     assert(xml_node);
359:     assert(node);
360: 
361:     child = freesasa_node_children(node);
362:     *xml_node = NULL;
363: 
364:     if (freesasa_node_type(node) == exclude_type) return FREESASA_SUCCESS;
365: 
366:     switch (freesasa_node_type(node)) {
367:     case FREESASA_NODE_STRUCTURE:
368:         *xml_node = structure2xml(node, options);
369:         break;
370:     case FREESASA_NODE_CHAIN:
371:         *xml_node = chain2xml(node, options);
372:         break;
373:     case FREESASA_NODE_RESIDUE:
374:         *xml_node = residue2xml(node, options);
375:         break;
376:     case FREESASA_NODE_ATOM:
377:         *xml_node = atom2xml(node, options);
378:         break;
379:     case FREESASA_NODE_ROOT:
380:     default:
381:         assert(0 && "tree illegal");
382:     }
383:     if (*xml_node == NULL)
384:         return fail_msg("error creating XML-node");
385: 
386:     /* simplify? */
387:     while (child != NULL) {
388:         if (node2xml(&xml_child, child, exclude_type, options) == FREESASA_FAIL) {
389:             return fail_msg("");
390:         }
391: 
392:         if (xml_child != NULL &&
393:             xmlAddChild(*xml_node, xml_child) == NULL) {
394:             xmlFreeNode(*xml_node);
395:             xmlFreeNode(xml_child);
396:             return fail_msg("");
397:         }
398:         child = freesasa_node_next(child);
399:     }
400: 
401:     return FREESASA_SUCCESS;
402: }
