159: template <typename T>
160: static freesasa_structure *
161: structure_from_pred(const gemmi::cif::Document &doc,
162:                     const T &discriminator,
163:                     const freesasa_classifier *classifier,
164:                     int structure_options)
165: {
166:     freesasa_structure *structure = freesasa_structure_new();
167:     std::string auth_atom_id;
168:     char prevAltId = '.';
169: 
170:     for (auto block : doc.blocks) {
171:         for (auto site : block.find("_atom_site.", atom_site_columns)) {
172:             if (site[0] != "ATOM" && !(structure_options & FREESASA_INCLUDE_HETATM)) {
173:                 continue;
174:             }
175: 
176:             if (discriminator(site)) continue;
177: 
178:             auto atom = freesasa_atom_from_site(site);
179: 
180:             if (!(structure_options & FREESASA_INCLUDE_HYDROGEN) && std::string(atom.type_symbol) == "H") {
181:                 continue;
182:             }
183: 
184:             // Pick the first alternative conformation for an atom
185:             auto currentAltId = site[6][0];
186:             if ((currentAltId != '.' && prevAltId == '.') || currentAltId == '.') {
187:                 prevAltId = currentAltId;
188:             } else if (currentAltId != '.' && currentAltId != prevAltId) {
189:                 continue;
190:             }
191: 
192:             freesasa_structure_add_cif_atom_lcl(structure, &atom, classifier, structure_options);
193: 
194:             // since this is in the interface between C and C++ code, some hackery is needed
195:             free((void *)atom.auth_atom_id);
196:         }
197:     }
198:     return structure;
199: }
