263: std::vector<freesasa_structure *>
264: freesasa_cif_structure_array(std::FILE *input,
265:                              int *n,
266:                              const freesasa_classifier *classifier,
267:                              int options)
268: {
269:     int n_models = 0, n_chains = 0;
270: 
271:     std::vector<freesasa_structure *> ss;
272: 
273:     auto doc_idx_pair = generate_gemmi_doc(input);
274:     auto &doc = doc_idx_pair.first;
275: 
276:     gemmi::Structure gemmi_struct = gemmi::make_structure_from_block(doc.blocks[0]);
277: 
278:     const auto models = gemmi_struct.models;
279: 
280:     n_models = models.size();
281: 
282:     /* only keep first model if option not provided */
283:     if (!(options & FREESASA_SEPARATE_MODELS)) n_models = 1;
284: 
285:     /* for each model read chains if requested */
286:     if (options & FREESASA_SEPARATE_CHAINS) {
287:         for (int i = 0; i < n_models; ++i) {
288:             auto chain_names = get_chains(models[i]);
289:             int n_new_chains = chain_names->size();
290:             n_chains += n_new_chains;
291: 
292:             if (n_new_chains == 0) {
293:                 freesasa_warn("in %s(): no chains found (in model %s)",
294:                               __func__, models[i].name.c_str());
295:                 continue;
296:             }
297: 
298:             ss.reserve(n_new_chains);
299:             for (auto &chain_name : *chain_names) {
300:                 freesasa_structure *structure = structure_from_chain(doc, models[i].name, chain_name, classifier, options);
301:                 if (freesasa_structure_n(structure) == 0) {
302:                     --n_chains;
303:                     free(structure);
304:                     continue;
305:                 }
306: 
307:                 ss.push_back(std::move(structure));
308: 
309:                 freesasa_structure_set_model(ss.back(), i + 1);
310:                 freesasa_structure_set_cif_ref(ss.back(), doc_idx_pair.second, NULL);
311:             }
312:         }
313:         if (n_chains == 0)
314:             freesasa_fail("In %s(): No chains in any model in protein: %s.",
315:                           __func__, gemmi_struct.name.c_str());
316:         *n = n_chains;
317:     } else {
318:         ss.reserve(n_models);
319:         for (int i = 0; i < n_models; ++i) {
320:             ss.emplace_back(
321:                 structure_from_model(doc, models[i].name, classifier, options));
322:             freesasa_structure_set_model(ss.back(), i + 1);
323:             freesasa_structure_set_cif_ref(ss.back(), doc_idx_pair.second, NULL);
324:         }
325:         *n = n_models;
326:     }
327: 
328:     // this is a hack, we only want to release docs once per input
329:     freesasa_structure_set_cif_ref(ss.back(), doc_idx_pair.second, &release_gemmi_doc);
330:     return ss;
331: }
