333: struct freesasa_MCRA {
334:     freesasa_MCRA(const int model,
335:                   const std::string &chain,
336:                   const std::string &res_num,
337:                   const std::string &residue,
338:                   const std::string &atom)
339:         : _model(model), _chain(chain), _res_num(res_num), _residue(residue), _atom(atom)
340:     {
341:     }
342: 
343:     int find_row(gemmi::cif::Table &table, int start_idx = 0) const
344:     {
345:         int idx = start_idx, total_rows = table.length();
346: 
347:         assert(idx < total_rows);
348: 
349:         while (idx < total_rows) {
350:             if (this->is_row(table[idx])) {
351:                 return idx;
352:             }
353:             ++idx;
354:         }
355: 
356:         freesasa_warn(
357:             "In %s(), unable to find row in _atom_site for atom (%d, %s, %s, %s, %s). "
358:             "Looping through entire table to double check...",
359:             __func__, this->_model, this->_chain.c_str(),
360:             this->_res_num.c_str(), this->_residue.c_str(),
361:             this->_atom.c_str());
362: 
363:         idx = 0;
364:         for (const auto site : table) {
365:             if (this->is_row(site)) {
366:                 return idx;
367:             }
368:             ++idx;
369:         }
370:         return FREESASA_FAIL;
371:     }
372: 
373: private:
374:     bool is_row(const gemmi::cif::Table::Row &row) const
375:     {
376:         int model = std::stoul(row[11]);
377:         const std::string &chain = row[1];
378:         const std::string &residue = row[4];
379:         const std::string &res_num = row[2];
380:         const std::string atom = row[5][0] != '"' ? row[5] : row[5].substr(1, row[5].size() - 2);
381: 
382:         if (_model == model) {
383:             if (_chain == chain) {
384:                 if (_res_num == res_num && _residue == residue) {
385:                     if (_atom == atom) {
386:                         return true;
387:                     }
388:                 }
389:             }
390:         }
391:         return false;
392:     }
393: 
394:     const int _model;
395:     const std::string &_chain, &_residue, &_res_num, &_atom;
396: };
