398: static void
399: append_freesasa_params_to_block(gemmi::cif::Block &block, freesasa_node *result)
400: {
401:     assert(freesasa_node_type(result) == FREESASA_NODE_RESULT);
402: 
403:     const freesasa_parameters *params = freesasa_node_result_parameters(result);
404: 
405:     std::string version{PACKAGE_STRING};
406:     version = version.substr(version.find(" "));
407: 
408:     if (params == NULL) params = &freesasa_default_parameters;
409: 
410:     std::string params_prefix{"_freeSASA_parameters."};
411: 
412:     std::vector<std::string> params_tags{"version", "algorithm", "probe-radius"};
413:     std::vector<std::string> params_data{
414:         version,
415:         std::string{freesasa_alg_name(params->alg)},
416:         std::to_string(params->probe_radius)};
417: 
418:     switch (params->alg) {
419:     case FREESASA_SHRAKE_RUPLEY:
420:         params_tags.emplace_back("testpoints");
421:         params_data.emplace_back(std::to_string(params->shrake_rupley_n_points));
422:         break;
423:     case FREESASA_LEE_RICHARDS:
424:         params_tags.emplace_back("slices");
425:         params_data.emplace_back(std::to_string(params->lee_richards_n_slices));
426:         break;
427:     default:
428:         assert(0);
429:         break;
430:     }
431: 
432:     for (int i = 0; i != params_tags.size(); ++i) {
433:         // place quotes around the algorithm tag value
434:         if (i == 1)
435:             block.set_pair(params_prefix + params_tags[i], gemmi::cif::quote(params_data[i]));
436:         else
437:             block.set_pair(params_prefix + params_tags[i], params_data[i]);
438:     }
439: }
