509: static int
510: append_freesasa_result_summary_to_block(gemmi::cif::Block &block, freesasa_node *result)
511: {
512:     assert(freesasa_node_type(result) == FREESASA_NODE_RESULT);
513: 
514:     freesasa_node *structure = NULL, *chain = NULL;
515:     const freesasa_nodearea *area = NULL;
516: 
517:     structure = freesasa_node_children(result);
518:     if (structure == NULL) {
519:         return freesasa_fail("Result node has no structure nodes.");
520:     }
521: 
522:     area = freesasa_node_area(structure);
523:     if (area == NULL) {
524:         return freesasa_fail("Structure node has no area.");
525:     }
526: 
527:     std::string results_prefix{"_freeSASA_results."};
528:     std::vector<std::string> result_tags{"model", "chains", "atoms", "type", "surface_area"};
529:     std::vector<std::string> template_data(result_tags.size());
530:     std::vector<std::vector<std::string>> result_data;
531: 
532:     template_data[0] = std::to_string(freesasa_node_structure_model(structure));
533:     template_data[1] = std::string{freesasa_node_structure_chain_labels(structure)};
534:     template_data[2] = std::to_string(freesasa_node_structure_n_atoms(structure));
535: 
536:     template_data[3] = "Total";
537:     template_data[4] = std::to_string(area->total);
538:     result_data.push_back(template_data);
539: 
540:     template_data[3] = "Apolar";
541:     template_data[4] = std::to_string(area->apolar);
542:     result_data.push_back(template_data);
543: 
544:     template_data[3] = "Polar";
545:     template_data[4] = std::to_string(area->polar);
546:     result_data.push_back(template_data);
547: 
548:     if (area->unknown > 0) {
549:         template_data[3] = "Unknown";
550:         template_data[4] = std::to_string(area->unknown);
551:         result_data.push_back(template_data);
552:     }
553: 
554:     chain = freesasa_node_children(structure);
555:     while (chain) {
556:         area = freesasa_node_area(chain);
557:         if (area == NULL) {
558:             return freesasa_fail("Chain has no stored area");
559:         }
560: 
561:         template_data[3] = gemmi::cif::quote(std::string{"CHAIN "} + std::string{freesasa_node_name(chain)});
562:         template_data[4] = std::to_string(area->total);
563:         result_data.push_back(template_data);
564: 
565:         chain = freesasa_node_next(chain);
566:     }
567: 
568:     gemmi::cif::Loop *result_loop;
569:     if (block.find(results_prefix, result_tags).ok()) {
570:         result_loop = block.find(results_prefix, result_tags).get_loop();
571:     } else {
572:         gemmi::cif::Loop &temp_loop = block.init_loop(results_prefix, result_tags);
573:         result_loop = &temp_loop;
574:     }
575: 
576:     for (auto &row : result_data) {
577:         result_loop->add_row(row);
578:     }
579: 
580:     return FREESASA_SUCCESS;
581: }
