583: static void
584: populate_freesasa_result_vectors(gemmi::cif::Table &table, freesasa_node *result,
585:                                  std::vector<std::string> &sasa_vals,
586:                                  std::vector<std::string> &sasa_radii)
587: {
588:     assert(freesasa_node_type(result) == FREESASA_NODE_RESULT);
589: 
590:     assert(table.ok());
591: 
592:     freesasa_node *structure, *chain, *residue, *atom;
593:     int rowNum{0}, model{0};
594: 
595:     structure = freesasa_node_children(result);
596:     while (structure) {
597:         rowNum = 0;
598:         model = freesasa_node_structure_model(structure);
599:         chain = freesasa_node_children(structure);
600:         while (chain) {
601:             residue = freesasa_node_children(chain);
602:             while (residue) {
603:                 append_freesasa_rsa_residue_to_block(table.bloc, residue);
604:                 atom = freesasa_node_children(residue);
605:                 while (atom) {
606:                     auto cName = std::string(freesasa_node_atom_chain(atom));
607:                     // TODO figure out why this returns decimal string sometimes
608:                     auto rNum = std::to_string(std::atoi(freesasa_node_atom_residue_number(atom)));
609:                     auto rName = freesasa_node_atom_residue_name(atom);
610:                     auto aName = freesasa_node_name(atom);
611:                     auto area = freesasa_node_area(atom);
612:                     auto radius = freesasa_node_atom_radius(atom);
613: 
614:                     rowNum = freesasa_MCRA{model, cName, rNum, rName, aName}.find_row(table, rowNum);
615:                     if (rowNum == FREESASA_FAIL)
616:                         freesasa_fail(
617:                             "In %s(), unable to find freesasa_node atom (%d, %s, %s, %s, %s) in cif %s",
618:                             __func__, model, cName.c_str(), rNum.c_str(), rName, aName, table.bloc.name.c_str());
619: 
620:                     sasa_vals[rowNum] = std::to_string(area->total);
621:                     sasa_radii[rowNum] = std::to_string(radius);
622: 
623:                     atom = freesasa_node_next(atom);
624:                 }
625:                 residue = freesasa_node_next(residue);
626:             }
627:             chain = freesasa_node_next(chain);
628:         }
629:         structure = freesasa_node_next(structure);
630:     }
631: }
