633: static int
634: replace_sasa_columns(gemmi::cif::Table &table,
635:                      const std::vector<std::string> &sasa_vals,
636:                      const std::vector<std::string> &sasa_radii,
637:                      const std::vector<std::string> &sasa_tags)
638: {
639:     std::vector<std::vector<std::string>> sasa_columns = {sasa_vals, sasa_radii};
640: 
641:     assert(sasa_columns.size() == sasa_tags.size());
642: 
643:     for (unsigned i = 0; i != sasa_tags.size(); ++i) {
644:         auto column = table.bloc.find_loop(sasa_tags[i]);
645:         std::copy(sasa_columns[i].begin(), sasa_columns[i].end(), column.begin());
646:     }
647: 
648:     return FREESASA_SUCCESS;
649: }
