651: static int
652: append_sasa_columns(gemmi::cif::Table &table,
653:                     const std::vector<std::string> &sasa_vals,
654:                     const std::vector<std::string> &sasa_radii,
655:                     const std::vector<std::string> &sasa_tags)
656: {
657:     auto &loop = *table.get_loop();
658: 
659:     unsigned long orig_tag_size = loop.tags.size();
660:     unsigned long new_tag_size = orig_tag_size + 2;
661: 
662:     // Creates a new table full of empty strings with the correct number of dimensions
663:     // Outside vector size is the # of columns, inside vector size is the # of rows.
664:     std::vector<std::vector<std::string>> new_columns(new_tag_size, {loop.length(), {"Empty"}});
665: 
666:     // Copies data from original columns to their respecitve column in the new table filled with empty strings.
667:     // Leaving only the new appended columns as empty strings
668:     for (unsigned i = 0; i != orig_tag_size; ++i) {
669:         auto column = table.bloc.find_loop(loop.tags[i]);
670:         std::copy(column.begin(), column.end(), new_columns[i].begin());
671:     }
672: 
673:     new_columns[new_tag_size - 2] = std::move(sasa_vals);
674:     new_columns[new_tag_size - 1] = std::move(sasa_radii);
675: 
676:     for (const auto &tag : sasa_tags)
677:         loop.tags.push_back(tag);
678: 
679:     loop.set_all_values(new_columns);
680: 
681:     return FREESASA_SUCCESS;
682: }
