684: static int
685: rewrite_atom_site(gemmi::cif::Table &table,
686:                   std::vector<std::string> &sasa_vals,
687:                   std::vector<std::string> &sasa_radii)
688: {
689:     std::vector<std::string> sasa_tags{
690:         "_atom_site.FreeSASA_value",
691:         "_atom_site.FreeSASA_radius"};
692: 
693:     auto &loop = *table.get_loop();
694: 
695:     if (loop.has_tag(sasa_tags[0]) && loop.has_tag(sasa_tags[1])) {
696:         return replace_sasa_columns(table, sasa_vals, sasa_radii, sasa_tags);
697:     } else {
698:         return append_sasa_columns(table, sasa_vals, sasa_radii, sasa_tags);
699:     }
