724: static int
725: write_result(std::ostream &out, freesasa_node *root)
726: {
727:     freesasa_node *result{freesasa_node_children(root)};
728: 
729:     size_t cif_ref, prev_cif_ref = 0;
730:     bool write = false;
731:     std::vector<std::string> sasa_vals, sasa_radii;
732: 
733:     while (result) {
734:         cif_ref = freesasa_node_structure_cif_ref(freesasa_node_children(result));
735:         if (docs.find(cif_ref) == docs.end()) {
736:             return freesasa_fail("In %s(), unable to find gemmi doc for result node: %s."
737:                                  "This can happen when using the --separate-chains option",
738:                                  __func__, freesasa_node_name(result));
739:         }
740: 
741:         auto &block = docs[cif_ref].sole_block();
742: 
743:         if (cif_ref != prev_cif_ref) {
744:             reset_freesasa_tables(block);
745:         }
746: 
747:         auto table = block.find("_atom_site.", atom_site_columns);
748:         if (prev_cif_ref != cif_ref) {
749:             sasa_vals = std::vector<std::string>{table.length(), "?"};
750:             sasa_radii = std::vector<std::string>{table.length(), "?"};
751:         }
752: 
753:         populate_freesasa_result_vectors(table, result, sasa_vals, sasa_radii);
754: 
755:         int added_data = rewrite_atom_site(table, sasa_vals, sasa_radii);
756:         int added_summary = append_freesasa_result_summary_to_block(block, result);
757: 
758:         if (added_data == FREESASA_FAIL || added_summary == FREESASA_FAIL) {
759:             return freesasa_fail("Unable to build CIF output");
760:         }
761: 
762:         append_freesasa_params_to_block(block, result);
763: 
764:         prev_cif_ref = cif_ref;
765:         result = freesasa_node_next(result);
766: 
767:         if (!result) {
768:             // There is no next result so write out current file.
769:             write = true;
770:         } else if (freesasa_node_structure_cif_ref(freesasa_node_children(result)) != prev_cif_ref) {
771:             // Next result node is from a new file so write out current file.
772:             write = true;
773:         } else {
774:             // Next result node is from the same doc so do not write current file yet.
775:             write = false;
776:         }
777: 
778:         if (write) gemmi::cif::write_cif_block_to_stream(out, block);
779:     }
780:     return FREESASA_SUCCESS;
781: }
