186:         return freesasa_warn("in %s(): empty coordinates", __func__);
187:     }
188: 
189:     if (n_threads > n_atoms) {
190:         n_threads = n_atoms;
191:         freesasa_warn("no sense in having more threads than atoms, only using %d threads",
192:                       n_threads);
