199: #if USE_THREADS
200:         return_value = lr_do_threads(n_threads, &lr);
201: #else
202:         return_value = freesasa_warn("in %s(): program compiled for single-threaded use, "
203:                                      "but multiple threads were requested, will "
204:                                      "proceed in single-threaded mode\n",
205:                                      __func__);
206:         n_threads = 1;
207: #endif /* pthread */
208:     }
209:     if (n_threads == 1) {
210:         for (i = 0; i < lr.n_atoms; ++i) {
211:             lr.sasa[i] = atom_area(&lr, i, 0);
