219: static int
220: lr_do_threads(int n_threads,
221:               lr_data *lr)
222: {
223:     pthread_t thread[MAX_LR_THREADS];
224:     lr_thread_interval t_data[MAX_LR_THREADS];
225:     int n_perthread = lr->n_atoms / n_threads, res;
226:     int threads_created = 0, return_value = FREESASA_SUCCESS;
227:     int t;
228: 
229:     for (t = 0; t < n_threads; ++t) {
230:         t_data[t].first_atom = t * n_perthread;
231:         if (t == n_threads - 1) {
232:             t_data[t].last_atom = lr->n_atoms - 1;
233:         } else {
234:             t_data[t].last_atom = (t + 1) * n_perthread - 1;
235:         }
236:         t_data[t].lr = lr;
237:         t_data[t].thread_id = t;
238:         res = pthread_create(&thread[t], NULL, lr_thread,
239:                              (void *)&t_data[t]);
240:         if (res) {
241:             return_value = fail_msg(freesasa_thread_error(res));
242:             break;
243:         }
244:         ++threads_created;
245:     }
246:     for (int t = 0; t < threads_created; ++t) {
247:         res = pthread_join(thread[t], NULL);
248:         if (res) {
249:             return_value = fail_msg(freesasa_thread_error(res));
250:         }
251:     }
252:     return return_value;
253: }
