255: static void *
256: lr_thread(void *arg)
257: {
258:     int i;
259:     lr_thread_interval *ti = ((lr_thread_interval *)arg);
260: 
261:     for (i = ti->first_atom; i <= ti->last_atom; ++i) {
262:         /* the different threads write to different parts of the
263:            array, so locking shouldn't be necessary */
264:         ti->lr->sasa[i] = atom_area(ti->lr, i, ti->thread_id);
265:     }
