270: static double
271: atom_area(lr_data *lr,
272:           int i,
273:           int thread_id)
274: {
275:     /* This function is large because a large number of pre-calculated
276:        arrays need to be accessed efficiently. Partially dereferenced
277:        here to make access more efficient.
278: 
279:        Variables are named according to the documentation (see page
280:        "Geometry of Lee & Richards' algorithm") */
281: 
282:     const int nni = lr->adj->nn[i];
283:     const double *restrict const v = freesasa_coord_all(lr->xyz);
284:     const double *restrict const R = lr->radii;
285:     const int *restrict const nbi = lr->adj->nb[i];
286:     const double *restrict const xydi = lr->adj->xyd[i];
287:     const double *restrict const xdi = lr->adj->xd[i];
288:     const double *restrict const ydi = lr->adj->yd[i];
289:     const double zi = v[3 * i + 2], Ri = R[i];
290:     const int ns = lr->n_slices_per_atom;
291: 
292:     int j, islice, n_arcs, is_buried, narc2;
293:     double *arc = lr->arc[thread_id],
294:            *z_nb = lr->z_nb[thread_id],
295:            *R_nb = lr->R_nb[thread_id];
296:     double z, delta, sasa = 0, alpha, beta, inf, sup;
297:     double zj, di, dj, dij, Rj, Ri_prime2, Ri_prime, Rj_prime2, Rj_prime;
298: 
299:     for (j = 0; j < nni; ++j) {
300:         z_nb[j] = v[3 * nbi[j] + 2];
301:         R_nb[j] = R[nbi[j]];
302:     }
303: 
304:     delta = 2 * Ri / ns;
305:     z = zi - Ri - 0.5 * delta;
306:     for (islice = 0; islice < ns; ++islice) {
307:         z += delta;
308:         di = fabs(zi - z);
309:         Ri_prime2 = Ri * Ri - di * di;
310:         if (Ri_prime2 < 0) continue; /* handle round-off errors */
311:         Ri_prime = sqrt(Ri_prime2);
312:         if (Ri_prime <= 0) continue; /* more round-off errors */
313:         n_arcs = 0;
314:         is_buried = 0;
315:         for (j = 0; j < nni; ++j) {
316:             zj = z_nb[j];
317:             dj = fabs(zj - z);
318:             Rj = R_nb[j];
319: 
320:             if (dj < Rj) {
321:                 Rj_prime2 = Rj * Rj - dj * dj;
322:                 Rj_prime = sqrt(Rj_prime2);
323:                 dij = xydi[j];
324:                 if (dij >= Ri_prime + Rj_prime) { /* atoms aren't in contact */
325:                     continue;
326:                 }
327:                 if (dij + Ri_prime < Rj_prime) { /* circle i is completely inside j */
328:                     is_buried = 1;
329:                     break;
330:                 }
331:                 if (dij + Rj_prime < Ri_prime) { /* circle j is completely inside i */
332:                     continue;
333:                 }
334:                 /* arc of circle i intersected by circle j */
335:                 alpha = acos((Ri_prime2 + dij * dij - Rj_prime2) / (2.0 * Ri_prime * dij));
336:                 /* position of mid-point of intersection along circle i */
337:                 beta = atan2(ydi[j], xdi[j]) + M_PI;
338:                 inf = beta - alpha;
339:                 sup = beta + alpha;
340:                 if (inf < 0) inf += TWOPI;
341:                 if (sup > 2 * M_PI) sup -= TWOPI;
342:                 narc2 = 2 * n_arcs;
343:                 /* store the arc, if arc passes 2*PI split into two */
344:                 if (sup < inf) {
345:                     /* store arcs as contiguous pairs of angles */
346:                     arc[narc2] = 0;
347:                     arc[narc2 + 1] = sup;
348:                     /* second arc */
349:                     arc[narc2 + 2] = inf;
350:                     arc[narc2 + 3] = TWOPI;
351:                     n_arcs += 2;
352:                 } else {
353:                     arc[narc2] = inf;
354:                     arc[narc2 + 1] = sup;
355:                     ++n_arcs;
356:                 }
357:             }
358:         }
359:         if (is_buried == 0) {
360:             sasa += delta * Ri * exposed_arc_length(arc, n_arcs);
361:         }
362:     }
363:     return sasa;
364: }
