366: /* insertion sort (faster than qsort for these short lists) */
367: inline static void
368: sort_arcs(double *restrict arc,
369:           int n)
370: {
371:     double tmp[2];
372:     double *end = arc + 2 * n, *arcj, *arci;
373:     for (arci = arc + 2; arci < end; arci += 2) {
374:         *tmp = *arci;
375:         *(tmp + 1) = *(arci + 1);
376:         arcj = arci;
377:         while (arcj > arc && *(arcj - 2) > tmp[0]) {
378:             *arcj = *(arcj - 2);
379:             *(arcj + 1) = *(arcj - 1);
380:             arcj -= 2;
381:         }
382:         *arcj = *tmp;
383:         *(arcj + 1) = *(tmp + 1);
384:     }
385: }
386: 
387: /* sort arcs by start-point, loop through them to sum parts of circle
388:    not covered by any of the arcs */
389: inline static double
390: exposed_arc_length(double *restrict arc,
391:                    int n)
392: {
393:     int i2;
394:     double sum, sup, tmp;
395: 
396:     if (n == 0) return TWOPI;
397: 
398:     sort_arcs(arc, n);
399:     sum = arc[0];
400:     sup = arc[1];
401:     /* in the following it is assumed that the arc[i2] <= arc[i2+1] */
402:     for (i2 = 2; i2 < 2 * n; i2 += 2) {
403:         if (sup < arc[i2]) sum += arc[i2] - sup;
404:         tmp = arc[i2 + 1];
405:         if (tmp > sup) sup = tmp;
406:     }
407:     return sum + TWOPI - sup;
408: }
